            inc hl
            dec bc
            cp 10
            jr nz, asm_1_439_n_hs_eol
            ld a, b                 ; the next line: CR LF - the headers' end?
            or a
            jr nz, asm_1_439_n_hs_two
            ld a, c
            cp 2
            jr c, asm_1_439_n_hs_done
