            ld b, a
            inc de
asm_1_439_n_hs_c1:
            ld a, (hl)
            or #20
            ex de, hl
            cp (hl)
            ex de, hl
            ret nz
            inc hl
            inc de
            djnz asm_1_439_n_hs_c1
asm_1_439_n_hs_c2:
            ld a, (hl)
            cp 32
            jr nz, asm_1_439_n_hs_c3
            inc hl
            jr asm_1_439_n_hs_c2
asm_1_439_n_hs_c3:
            xor a
            ret
